using System.Net;
using System.Runtime.InteropServices;
using System.Text.Json;
using SysAdminAssistant.Core;
namespace SysAdminAssistant.Server;
public sealed class ServerNetworkAccess
{
    private readonly Func<string[],string> firewallWriter;private readonly string path;private string[] current;private readonly object gate=new();private string firewall="Windows Firewall — отдельный уровень доступа; после изменения проверьте его статус";
    public ServerNetworkAccess(string directory,string[] installed,Func<string[],string>? firewallWriter=null){this.firewallWriter=firewallWriter??UpdateFirewall;path=Path.Combine(directory,"trusted-networks.json");current=ServerNetworkRules.Validate(File.Exists(path)?JsonSerializer.Deserialize<string[]>(File.ReadAllText(path))??throw new InvalidDataException(global::SysAdminAssistant.Core.ProductText.Get("Пустые доверенные сети")):installed);}
    public bool Allows(IPAddress peer)=>ServerNetworkRules.Allows(Volatile.Read(ref current),peer);
    public ServerNetworksView View(IPAddress peer){lock(gate)return new(current.ToArray(),ServerNetworkRules.Revision(current),peer.ToString(),firewall,ServerNetworkRules.FirewallCommand(current));}
    public ServerNetworksView Save(ServerNetworksSave request,IPAddress peer){lock(gate){var next=ServerNetworkRules.Validate(request.Networks);if(request.Revision!=ServerNetworkRules.Revision(current))throw new ArgumentException(global::SysAdminAssistant.Core.ProductText.Get("Сети изменены другим администратором. Откройте настройки заново"));if(!request.AllowDisconnect&&!ServerNetworkRules.Allows(next,peer))throw new ArgumentException(global::SysAdminAssistant.Core.ProductText.Get("Новый список исключает адрес текущего клиента. Требуется отдельное подтверждение"));var previous=path+".previous";if(File.Exists(path))File.Copy(path,previous,true);else File.WriteAllText(previous,JsonSerializer.Serialize(current));var temp=path+".tmp";using(var f=new FileStream(temp,FileMode.Create,FileAccess.Write,FileShare.None)){JsonSerializer.Serialize(f,next);f.Flush(true);}File.Move(temp,path,true);Volatile.Write(ref current,next);firewall=firewallWriter(next);return View(peer);}}
    private static string UpdateFirewall(string[] next){object? policy=null;object? rule=null;try{if(!OperatingSystem.IsWindows())return "Windows Firewall недоступен в этой ОС";policy=Activator.CreateInstance(Type.GetTypeFromProgID("HNetCfg.FwPolicy2",true)!)!;rule=((dynamic)policy).Rules.Item("SysAdminAssistantServer-LAN");((dynamic)rule).RemoteAddresses=string.Join(",",next);return "Windows Firewall: доверенные сети обновлены";}catch(Exception e)when(e is COMException or UnauthorizedAccessException or System.Reflection.TargetInvocationException or Microsoft.CSharp.RuntimeBinder.RuntimeBinderException){return "Список сервера сохранён. Windows Firewall не изменён: нужны права локального администратора или штатное правило отсутствует. Выполните показанную команду на сервере";}finally{if(OperatingSystem.IsWindows()){if(rule!=null&&Marshal.IsComObject(rule))Marshal.FinalReleaseComObject(rule);if(policy!=null&&Marshal.IsComObject(policy))Marshal.FinalReleaseComObject(policy);}}}
}
